class Solution {
    struct Cell {
        int h, r, c;
        bool operator>(const Cell& o) const {
            return h > o.h;
        }
    };
public:
    int trapRainWater(vector<vector<int>>& heightMap) {
        if (heightMap.empty() || heightMap[0].empty()) return 0;
        int m = heightMap.size(), n = heightMap[0].size();
        priority_queue<Cell, vector<Cell>, greater<Cell>> pq;
        vector<vector<bool>> visited(m, vector<bool>(n, false));

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (r == 0 || r == m - 1 || c == 0 || c == n - 1) {
                    pq.push({heightMap[r][c], r, c});
                    visited[r][c] = true;
                }
            }
        }

        int totalWater = 0;
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!pq.empty()) {
            auto curr = pq.top();
            pq.pop();
            for (int d = 0; d < 4; d++) {
                int nr = curr.r + dirs[d][0];
                int nc = curr.c + dirs[d][1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    totalWater += max(0, curr.h - heightMap[nr][nc]);
                    pq.push({max(curr.h, heightMap[nr][nc]), nr, nc});
                }
            }
        }
        return totalWater;
    }
};

class Solution {
    static class Cell implements Comparable<Cell> {
        int h, r, c;
        Cell(int h, int r, int c) {
            this.h = h;
            this.r = r;
            this.c = c;
        }
        public int compareTo(Cell o) {
            return Integer.compare(this.h, o.h);
        }
    }

    public int trapRainWater(int[][] heightMap) {
        if (heightMap == null || heightMap.length == 0 || heightMap[0].length == 0) return 0;
        int m = heightMap.length, n = heightMap[0].length;
        PriorityQueue<Cell> pq = new PriorityQueue<>();
        boolean[][] visited = new boolean[m][n];

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (r == 0 || r == m - 1 || c == 0 || c == n - 1) {
                    pq.offer(new Cell(heightMap[r][c], r, c));
                    visited[r][c] = true;
                }
            }
        }

        int totalWater = 0;
        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        while (!pq.isEmpty()) {
            Cell curr = pq.poll();
            for (int[] d : dirs) {
                int nr = curr.r + d[0];
                int nc = curr.c + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    totalWater += Math.max(0, curr.h - heightMap[nr][nc]);
                    pq.offer(new Cell(Math.max(curr.h, heightMap[nr][nc]), nr, nc));
                }
            }
        }
        return totalWater;
    }
}

var trapRainWater = function(heightMap) {
    if (!heightMap || !heightMap.length || !heightMap[0].length) return 0;
    const m = heightMap.length, n = heightMap[0].length;
    const visited = Array.from({ length: m }, () => new Array(n).fill(false));

    class MinHeap {
        constructor() { this.data = []; }
        push(val) {
            this.data.push(val);
            this._up(this.data.length - 1);
        }
        pop() {
            if (!this.data.length) return null;
            const top = this.data[0];
            const bottom = this.data.pop();
            if (this.data.length) {
                this.data[0] = bottom;
                this._down(0);
            }
            return top;
        }
        size() { return this.data.length; }
        _up(i) {
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.data[p].h <= this.data[i].h) break;
                [this.data[p], this.data[i]] = [this.data[i], this.data[p]];
                i = p;
            }
        }
        _down(i) {
            const len = this.data.length;
            while ((i << 1) + 1 < len) {
                let left = (i << 1) + 1;
                let right = left + 1;
                let best = (right < len && this.data[right].h < this.data[left].h) ? right : left;
                if (this.data[i].h <= this.data[best].h) break;
                [this.data[i], this.data[best]] = [this.data[best], this.data[i]];
                i = best;
            }
        }
    }

    const pq = new MinHeap();
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            if (r === 0 || r === m - 1 || c === 0 || c === n - 1) {
                pq.push({ h: heightMap[r][c], r, c });
                visited[r][c] = true;
            }
        }
    }

    let totalWater = 0;
    const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    while (pq.size() > 0) {
        const curr = pq.pop();
        for (const [dr, dc] of dirs) {
            const nr = curr.r + dr;
            const nc = curr.c + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc]) {
                visited[nr][nc] = true;
                totalWater += Math.max(0, curr.h - heightMap[nr][nc]);
                pq.push({ h: Math.max(curr.h, heightMap[nr][nc]), r: nr, c: nc });
            }
        }
    }
    return totalWater;
};
